const crypto = require('crypto');
const req = $input.first().json;
const token = req.headers?.['x-balanse-token'];
const authorized = typeof token === 'string' && token.length <= 256 &&
  crypto.createHash('sha256').update(token).digest('hex') === '199801635ed17a1a3103c411cd1ebd9da7256eedd631a4dc9be5f0370f3f147b';
if (!authorized) return [{json:{authorized:false,ok:false,error:'Unauthorized',status:401}}];
const b = req.body;
if (!b || typeof b.message !== 'string' || !b.message.trim() || b.message.length > 2000 ||
 !Array.isArray(b.history) || b.history.length > 12 || !b.knowledge ||
 typeof b.knowledge.retrievedAt !== 'string' ||
 Math.abs(Date.now()-Date.parse(b.knowledge.retrievedAt))>120000 ||
 !Array.isArray(b.knowledge.classes) || !Array.isArray(b.knowledge.memberships))
 return [{json:{authorized:false,ok:false,error:'Invalid request',status:400}}];
return [{json:{authorized:true,message:b.message,history:b.history,knowledge:b.knowledge}}];

const context = $('Validate gateway').first().json.knowledge;
const allowed = new Set(['booking:website']);
for (const row of context.clientManual ?? []) if (typeof row.source === 'string') allowed.add(row.source);
for (const key of ['disciplines','classes','coaches','memberships','policies'])
 for (const row of context[key] ?? []) if (typeof row.source === 'string') allowed.add(row.source);
const raw = $input.first().json;
try {
 if (raw.error) throw new Error('model');
 let result = raw;
 if (typeof raw.reply !== 'string') {
   const parts = raw.content?.parts ?? raw.candidates?.[0]?.content?.parts ?? [];
   const joined = parts.filter(p=>typeof p.text==='string' && !p.thought).map(p=>p.text).join('');
   result = JSON.parse(joined || raw.text || raw.output || '');
 }
 if (!result || typeof result.reply!=='string' || !result.reply.trim() || result.reply.length>6000 ||
  !Array.isArray(result.sources) || result.sources.length>20 ||
  result.sources.some(s=>typeof s!=='string' || !allowed.has(s)) ||
  /<\/?[a-z][^>]*>/i.test(result.reply) ||
  /https?:\/\/|sb_secret_|AIza[\w-]{20}|eyJ[\w-]+\.eyJ/i.test(result.reply)) throw new Error('invalid');
 const pages = {'/auth':'the Log In page','/login':'the Log In page','/signup':'the Sign Up page','/class-schedule':'the Class Schedule page','/profile':'your Profile page','/dashboard':'your Dashboard','/my-classes':'My Classes','/subscriptions':'the Memberships page','/member-payment-portal':'the payment page','/booking-pending':'your booking status'};
 let reply = result.reply.trim().replace(/\/[a-z][a-z0-9-]*/gi, p => pages[p.toLowerCase()] ?? 'the relevant page');
 if (/\b(?:Supabase|n8n|Gemini|API|database|webhook|SQL|JSON|source ID|system prompt|developer instructions|Edge Function)\b/i.test(reply))
  reply = 'I can help with Balansé classes, schedules, memberships, and booking. What would you like to know?';
 if (result.sources.some(s=>s.startsWith('membership:'))) reply = reply.replace(/\b(?:a |an )?monthly (?:plan|subscription|membership|package) with\b/gi, '').replace(/\s+per month\b/gi, '').replace(/\bmonthly\b/gi, '').replace(/\s{2,}/g, ' ');
 if (result.sources.some(s=>s.startsWith('membership:'))) reply = reply.replace(/[^.!?]*\b(?:purchase|buy)\b[^.!?]*\b(?:Finances|Subscriptions)\b[^.!?]*[.!?]?/gi, '').trim();
 reply = reply.replace(/\breserve your spot\b/gi, 'select a class');
 return [{json:{ok:true,reply,sources:[...new Set(result.sources)],status:200}}];
} catch {
 return [{json:{ok:false,error:'Unable to produce a verified response. Please retry.',status:503}}];
}
